import {$,esc,showToast} from "./dom.js";
import {appState,placeholders,products,productSources,recentPropertyIds,rules,newRule} from "./state.js";
import {renderAnnotations} from "./annotations.js";

const steps=[[1,"消息内容","分类、内容与跳转"],[2,"触发条件","触发源和提醒时间"],[3,"投递设置","送到哪里、怎么发送"]];
const product=()=>products.find(item=>item.id===appState.selectedProductId)||products[0];
const sources=()=>productSources[appState.selectedProductId]||{properties:[],countdowns:[],consumables:[]};
const mode=()=>appState.rule.reminderMode;
let pickerState={query:"",group:"all"};

function stepNav(){return `<nav class="step-nav" id="ruleStepNav" data-anchor="step-nav"><div class="step-progress"><span>规则配置</span><strong>步骤 ${appState.ruleStep} / 3</strong></div><ol class="step-list">${steps.map(([number,title,subtitle],index)=>`<li class="step-slot"><button class="step-item ${number===appState.ruleStep?"active":""} ${number<appState.ruleStep?"is-complete":""}" data-step="${number}"><span class="step-index">${number<appState.ruleStep?"✓":number}</span><span class="step-copy"><strong>${title}</strong><small>${subtitle}</small></span></button>${index<2?'<span class="step-connector"></span>':""}</li>`).join("")}</ol></nav>`}
const propertyType=property=>property.type==="number"?"数值":property.type==="enum"?"枚举":"开关";
const propertyMeta=property=>[property.id,propertyType(property),property.unit].filter(Boolean).join(" · ");
const groups=()=>[...new Set(sources().properties.map(property=>property.group||"其他"))];
function matchingProperties(){const keyword=pickerState.query.trim().toLowerCase();return sources().properties.filter(property=>{const inGroup=pickerState.group==="all"||property.group===pickerState.group;const content=[property.name,property.id,property.description,property.group].filter(Boolean).join(" ").toLowerCase();return inGroup&&(!keyword||content.includes(keyword))})}
function selectProperty(property){appState.rule.propertyId=property.id;appState.rule.operator=property.operators?.[0]||"=";appState.rule.propertyValue=property.type==="enum"?property.options?.[0]||"":property.type==="boolean"?"true":property.example||""}
function propertyRow(property){const selected=property.id===appState.rule.propertyId;return `<button type="button" class="property-option ${selected?"selected":""}" data-select-property="${esc(property.id)}"><span class="property-type-icon">${property.type==="number"?"#":property.type==="enum"?"≡":"✓"}</span><span class="property-option-copy"><strong>${esc(property.name)}</strong><small>${esc(propertyMeta(property))}</small></span><span class="property-option-side"><span class="el-tag el-tag--info is-plain">${esc(property.group||"其他")}</span>${selected?"<b>已选</b>":"<span>选择</span>"}</span></button>`}
function pickerShell(){const all=sources().properties,rows=matchingProperties(),recent=(recentPropertyIds[appState.selectedProductId]||[]).map(id=>all.find(property=>property.id===id)).filter(Boolean),current=all.find(property=>property.id===appState.rule.propertyId);return `<div class="property-picker-host is-open" id="propertyPicker"><div class="property-picker-mask" data-picker-close></div><section class="property-picker" role="dialog" aria-modal="true" aria-label="选择设备属性"><header class="property-picker-header"><div><h3>选择设备属性</h3><p>当前产品有 ${all.length} 个属性，可用搜索或分组快速找到。</p></div><button type="button" class="icon-btn" data-picker-close aria-label="关闭">×</button></header><div class="property-picker-toolbar"><div class="property-search"><span>⌕</span><input class="el-input" data-property-query value="${esc(pickerState.query)}" placeholder="搜索属性名称或标识符" autocomplete="off"><kbd>Esc</kbd></div><div class="property-current">当前选择：<strong>${esc(current?.name||"未选择")}</strong><span>${esc(current?propertyMeta(current):"")}</span></div></div><div class="property-picker-body"><aside class="property-group-list" aria-label="属性分组"><button type="button" class="property-group ${pickerState.group==="all"?"active":""}" data-property-group="all"><span>全部属性</span><b>${all.length}</b></button>${groups().map(group=>`<button type="button" class="property-group ${pickerState.group===group?"active":""}" data-property-group="${esc(group)}"><span>${esc(group)}</span><b>${all.filter(property=>property.group===group).length}</b></button>`).join("")}</aside><section class="property-results"><div class="property-results-head"><span>${pickerState.query?`“${esc(pickerState.query)}” 的结果`:(pickerState.group==="all"?"全部属性":esc(pickerState.group))}</span><small>${rows.length} 个可选</small></div>${!pickerState.query&&pickerState.group==="all"&&recent.length?`<div class="property-recent"><span>最近使用</span><div>${recent.map(property=>`<button type="button" data-select-property="${esc(property.id)}">${esc(property.name)}<small>${esc(property.id)}</small></button>`).join("")}</div></div>`:""}<div class="property-option-list">${rows.length?rows.map(propertyRow).join(""):`<div class="property-empty"><strong>没有找到匹配属性</strong><span>试试其他名称或切换分组。</span><button type="button" class="op-link" data-picker-reset>清空搜索</button></div>`}</div></section></div><footer class="property-picker-footer"><span>属性来自当前产品的功能设计。</span><button type="button" class="el-btn" data-picker-close>取消</button></footer></section></div>`}
function closePicker(){const host=$("#propertyPicker");if(host)host.remove()}
function rerenderPicker(){const host=$("#propertyPicker");if(!host)return;host.outerHTML=pickerShell();wirePicker();$("[data-property-query]",$("#propertyPicker"))?.focus()}
function wirePicker(){const host=$("#propertyPicker");if(!host)return;host.querySelectorAll("[data-picker-close]").forEach(button=>button.onclick=closePicker);host.querySelector("[data-property-query]")?.addEventListener("input",event=>{pickerState.query=event.target.value;rerenderPicker()});host.querySelectorAll("[data-property-group]").forEach(button=>button.onclick=()=>{pickerState.group=button.dataset.propertyGroup;rerenderPicker()});host.querySelector("[data-picker-reset]")?.addEventListener("click",()=>{pickerState={query:"",group:"all"};rerenderPicker()});host.querySelectorAll("[data-select-property]").forEach(button=>button.onclick=()=>{const next=sources().properties.find(property=>property.id===button.dataset.selectProperty);if(!next)return;selectProperty(next);closePicker();rerender();showToast(`已选择：${next.name}`)});host.addEventListener("keydown",event=>{if(event.key==="Escape")closePicker()})}
function openPicker(){pickerState={query:"",group:"all"};$("#overlayRoot").insertAdjacentHTML("beforeend",pickerShell());wirePicker();requestAnimationFrame(()=>$('[data-property-query]',$("#propertyPicker"))?.focus())}

function sourceCapability(source,kind){if(!source)return `<div class="help-alert warning">当前产品没有可用的${kind}，这条规则暂时不能启用。</div>`;const ready=source.deviceCapability==="verified"&&(kind!=="云计时器"||source.cycleContract==="verified");return `<div class="help-alert ${ready?"success":"warning"}"><strong>${ready?"可以使用":"暂不能使用"}</strong> · ${kind}需要能识别到设备。来源异常时不发送提醒。</div>`}
function timeWindow(){const rule=appState.rule,cross=rule.timeStart>rule.timeEnd;return `<div class="form-section" data-anchor="trigger-time"><div class="section-title"><h3>提醒时间</h3><p>按每天的时间段发送</p></div><div class="time-range"><input class="el-input" type="time" data-rule="timeStart" value="${esc(rule.timeStart)}"><span>至</span><input class="el-input" type="time" data-rule="timeEnd" value="${esc(rule.timeEnd)}"><span class="el-tag el-tag--${cross?"warning":"info"} is-plain">${cross?"跨到次日":"当天"}</span></div><p class="form-help">只有在这个时间段内发生，才会发送提醒。比如 23:00 至 01:00，表示晚上 11 点到第二天凌晨 1 点。</p></div>`}
function trigger(){const rule=appState.rule,source=sources(),property=source.properties.find(item=>item.id===rule.propertyId)||source.properties[0],lockedToCloud=rule.category==="云计时器通知",choices=lockedToCloud?[["cloud","云端触发","计时器剩余时长到达设置值"]]:[["device","设备触发","属性满足条件时提醒"],["cloud","云端触发","计时器剩余时长到达设置值"],["consumable","耗材触发","耗材不足或耗尽时提醒"]];let detail="";
  if(rule.triggerType==="device")detail=`<div class="form-grid"><div class="form-row" data-anchor="property-selector"><span class="form-label"><i class="required">*</i>设备属性</span><button type="button" class="property-select-trigger" data-open-property-picker><span class="property-select-main"><strong>${esc(property?.name||"请选择属性")}</strong><small>${esc(property?propertyMeta(property):"")}</small></span><span class="property-select-action">选择 / 更换 ›</span></button><p class="form-help">支持按名称或标识符搜索，也可以按分组查看。</p></div><label class="form-row"><span class="form-label"><i class="required">*</i>条件</span><select class="el-select" data-rule="operator">${(property?.operators||[]).map(item=>`<option ${item===rule.operator?"selected":""}>${item}</option>`).join("")}</select></label><label class="form-row full"><span class="form-label"><i class="required">*</i>条件值</span>${property?.type==="enum"?`<select class="el-select" data-rule="propertyValue">${property.options.map(item=>`<option ${item===rule.propertyValue?"selected":""}>${item}</option>`).join("")}</select>`:property?.type==="boolean"?`<select class="el-select" data-rule="propertyValue"><option value="true" ${rule.propertyValue==="true"?"selected":""}>是</option><option value="false" ${rule.propertyValue==="false"?"selected":""}>否</option></select>`:`<input class="el-input" data-rule="propertyValue" value="${esc(rule.propertyValue)}" placeholder="例如 ${property?.example||"1"}">`}<p class="form-help">当 ${esc(property?.name||"属性")} ${esc(rule.operator)} ${esc(rule.propertyValue)}${property?.unit?` ${property.unit}`:""} 时，满足提醒条件。</p></label></div>`;
  if(rule.triggerType==="cloud"){const timer=source.countdowns.find(item=>item.id===rule.cloudCountdownId)||source.countdowns[0],unit=timer?.unit||"分钟",limit=timer?.duration;detail=`<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>云计时器</span><select class="el-select" data-rule="cloudCountdownId">${source.countdowns.map(item=>`<option value="${item.id}" ${item.id===rule.cloudCountdownId?"selected":""}>${item.name} · 每 ${item.duration} ${item.unit}</option>`).join("")||'<option value="">当前产品暂无云计时器</option>'}</select></label><label class="form-row"><span class="form-label"><i class="required">*</i>剩余时长</span><div class="threshold-control"><input class="el-input" type="number" min="0" step="1" ${Number.isFinite(limit)?`max="${limit}"`:""} data-rule="cloudThresholdMinutes" value="${esc(rule.cloudThresholdMinutes)}"><span>${esc(unit)}</span></div><p class="form-help">剩余时长少于或等于 ${esc(rule.cloudThresholdMinutes||"未设置")} ${esc(unit)} 时提醒。计时器按 ${esc(unit)} 配置，这里也使用 ${esc(unit)}。</p></label></div>${sourceCapability(timer,"云计时器")}`}
  if(rule.triggerType==="consumable"){const consumable=source.consumables.find(item=>item.id===rule.consumableId);detail=`<div class="form-grid"><label class="form-row"><span class="form-label"><i class="required">*</i>耗材项</span><select class="el-select" data-rule="consumableId">${source.consumables.map(item=>`<option value="${item.id}" ${item.id===rule.consumableId?"selected":""}>${item.name}</option>`).join("")||'<option value="">当前产品暂无配置耗材</option>'}</select></label><label class="form-row"><span class="form-label"><i class="required">*</i>触发项</span><select class="el-select" data-rule="consumableEvent"><option value="low" ${rule.consumableEvent==="low"?"selected":""}>不足</option><option value="empty" ${rule.consumableEvent==="empty"?"selected":""}>耗尽</option></select></label></div>${sourceCapability(consumable,"耗材")}`}
  return `<div class="form-section" data-anchor="trigger-source"><div class="section-title"><h3>触发源</h3><p>${lockedToCloud?"云计时器通知固定使用云端触发":"选择当前产品已有的来源"}</p></div>${lockedToCloud?'<div class="help-alert warning">已选择云计时器通知，触发源固定为云端触发。</div>':""}<div class="radio-row">${choices.map(([value,title,subtitle])=>`<label class="choice-card ${rule.triggerType===value?"selected":""}"><input type="radio" name="trigger" value="${value}" ${rule.triggerType===value?"checked":""}><span class="choice-copy"><strong>${title}</strong><small>${subtitle}</small></span></label>`).join("")}</div><div class="trigger-detail">${detail}</div></div>${timeWindow()}<div class="form-section" data-anchor="recipient-resolution"><div class="section-title"><h3>接收者</h3><p>系统自动处理</p></div><div class="help-alert">每次触发都对应一台设备，提醒会发给这台设备已绑定的用户。没有绑定用户时，不发送提醒。</div></div>`}

function basic(){const rule=appState.rule,message=appState.message.values["en-US"]||{title:"",body:""};return `<div class="form-section"><div class="section-title"><h3>基础信息</h3><p>规则归属当前产品</p></div><div class="form-grid"><label class="form-row full"><span class="form-label"><i class="required">*</i>规则名称</span><input class="el-input" data-rule="name" value="${esc(rule.name)}" placeholder="例如：储奶量过高提醒"></label><label class="form-row"><span class="form-label"><i class="required">*</i>消息分类</span><select class="el-select" data-rule="category"><option ${rule.category==="云计时器通知"?"selected":""}>云计时器通知</option><option ${rule.category!=="云计时器通知"?"selected":""}>事件通知</option></select><p class="form-help">用于列表查询；云计时器通知会和同日同设备的同类提醒合并发送。</p></label><label class="form-row"><span class="form-label">当前产品</span><div class="readonly-field">${esc(product().name)}</div></label></div>${rule.category==="云计时器通知"?'<div class="help-alert warning">云计时器通知固定使用云端触发；同一台设备当天有多条这类提醒时，系统会合成一条提醒。</div>':""}</div><div class="form-section" data-anchor="message-editor"><div class="section-title"><h3>推送消息 · English</h3><p>English 是默认内容</p></div><label class="form-row full"><span class="form-label"><i class="required">*</i>Title</span><input class="el-input" data-content="title" maxlength="100" value="${esc(message.title)}"></label><label class="form-row full"><span class="form-label"><i class="required">*</i>Body</span><textarea class="el-textarea" data-content="body" maxlength="200">${esc(message.body)}</textarea></label><div class="placeholder-area" data-anchor="placeholder-panel"><div><strong>插入内容</strong><span>当前：${appState.activeContentField==="body"?"Body":"Title"}</span></div><div class="placeholder-panel">${placeholders.map(token=>`<button type="button" class="placeholder" data-insert-placeholder="${esc(token)}">${esc(token)}</button>`).join("")}</div><p class="form-help">先点击 Title 或 Body，再选择要插入的内容。</p></div></div><div class="form-section" data-anchor="jump-mode"><div class="section-title"><h3>点击后打开</h3><p>默认进入 App 消息中心</p></div><select class="el-select" data-preset>${product().presetLinks.map(item=>`<option value="${item.id}" ${item.id===rule.presetLinkId?"selected":""}>${item.label}</option>`).join("")}</select><p class="form-help">选择系统通知时，用户点击 iOS 或 Android 的通知，也会进入这里选择的页面。</p></div><div class="form-section"><div class="section-title"><h3>统一多语言</h3><p>所有规则在产品级大表中一起维护</p></div><div class="help-alert success">请回到规则列表，点击「统一多语言」选择语言并录入翻译。当前规则保存后会自动出现在大表中。</div></div>`}

function delivery(){const rule=appState.rule,discard=mode()==="discard",merge=rule.category==="云计时器通知"&&rule.triggerType==="cloud",systemNotification=!!rule.systemNotificationEnabled;return `<div class="form-section" data-anchor="delivery-target"><div class="section-title"><h3>投递目标</h3><p>App 消息中心始终接收提醒</p></div><div class="radio-row"><div class="choice-card selected"><span class="choice-copy"><strong>App 消息中心 <span class="el-tag el-tag--success is-plain">必选</span></strong><small>每条提醒都会写入 App 消息中心，不能关闭</small></span></div><label class="choice-card ${systemNotification?"selected":""}"><input type="checkbox" name="system-notification" ${systemNotification?"checked":""}><span class="choice-copy"><strong>同时发送系统通知</strong><small>可选发送到手机通知栏，点击后进入已选页面</small></span></label></div></div><div class="form-section" data-anchor="delivery-mode"><div class="section-title"><h3>发送方式</h3><p>控制同一条规则重复提醒的方式</p></div><div class="radio-row"><label class="choice-card ${!discard?"selected":""}"><input type="radio" name="mode" value="each" ${!discard?"checked":""}><span class="choice-copy"><strong>逐条发送</strong><small>每次满足条件都发送</small></span></label><label class="choice-card ${discard?"selected":""}"><input type="radio" name="mode" value="discard" ${discard?"checked":""}><span class="choice-copy"><strong>仅发送首条</strong><small>一段时间内只发第一次提醒</small></span></label></div>${discard?`<label class="form-row interval-field" data-anchor="min-interval"><span class="form-label"><i class="required">*</i>最小发送间隔</span><div class="threshold-control"><input class="el-input" type="number" min="5" max="10080" data-rule="minIntervalMinutes" value="${esc(rule.minIntervalMinutes)}"><span>分钟</span></div><p class="form-help">设置为 ${esc(rule.minIntervalMinutes)} 分钟后，这段时间内只发送第一次提醒。</p></label>`:""}</div>${merge?`<div class="form-section" data-anchor="same-day-merge"><div class="section-title"><h3>同日合并</h3><p>云计时器通知自动处理</p></div><div class="help-alert success">同一台设备当天有多条云计时器通知时，会合成一条提醒；当天只有一条时，按这条规则正常发送。</div></div>`:""}<div class="form-section" data-anchor="frequency-timeline"><div class="section-title"><h3>发送示例</h3><p>${merge?"同日合并":discard?"仅发送首条":"逐条发送"}</p></div><div class="timeline"><div class="timeline-row"><span class="timeline-dot active"></span><strong>第一次满足条件</strong><small>${systemNotification?"写入消息中心，同时发送系统通知":"写入 App 消息中心"}</small><span>立即发送</span></div>${discard?'<div class="timeline-row"><span class="timeline-dot"></span><strong>间隔内再次满足</strong><small>不再重复提醒</small><span>不发送</span></div>':""}${merge?'<div class="timeline-row"><span class="timeline-dot"></span><strong>当天还有云计时器通知</strong><small>和当天的提醒放在一起</small><span>合成一条</span></div>':""}</div></div><div class="form-section" data-anchor="validation"><div class="section-title"><h3>保存检查</h3><p>确认主要配置是否完整</p></div>${validation()}</div>`}

function validation(){const rule=appState.rule,source=rule.triggerType==="cloud"?sources().countdowns.find(item=>item.id===rule.cloudCountdownId):rule.triggerType==="consumable"?sources().consumables.find(item=>item.id===rule.consumableId):null,property=sources().properties.find(item=>item.id===rule.propertyId),message=appState.message.values["en-US"]||{},cloudValue=Number(rule.cloudThresholdMinutes),cloudOk=rule.triggerType!=="cloud"||!!source&&Number.isInteger(cloudValue)&&cloudValue>=0&&cloudValue<=source.duration,deviceOk=rule.triggerType!=="device"||!!property&&property.operators.includes(rule.operator)&&String(rule.propertyValue||"").trim()!=="",consumableOk=rule.triggerType!=="consumable"||!!source,timeOk=!!rule.timeStart&&!!rule.timeEnd&&rule.timeStart!==rule.timeEnd,categoryOk=rule.category!=="云计时器通知"||rule.triggerType==="cloud",intervalOk=mode()==="each"||(+rule.minIntervalMinutes>=5&&+rule.minIntervalMinutes<=10080),checks=[[!!rule.name.trim(),"规则名称"],[!!message.title?.trim()&&!!message.body?.trim(),"English 内容"],[deviceOk,"设备条件"],[cloudOk,"云端计时器和剩余时长"],[consumableOk,"耗材来源"],[timeOk,"提醒时间"],[categoryOk,"云计时器通知使用云端触发"],[intervalOk,"最小发送间隔"]];return `<div class="validation-list">${checks.map(([ok,text])=>`<div class="validation-item ${ok?"":"validation-fail"}"><span>${ok?"✓":"!"} ${text}</span><span class="el-tag el-tag--${ok?"success":"danger"} is-plain">${ok?"通过":"请完善"}</span></div>`).join("")}</div>`}

function content(){return appState.ruleStep===1?basic():appState.ruleStep===2?trigger():delivery()}
function shell(){return `<div class="drawer-host is-open" id="ruleDrawer"><div class="drawer-mask" data-close></div><aside class="drawer"><header class="drawer-header"><div class="drawer-title"><h2>${appState.editingRule?"编辑":"新建"}推送规则</h2><p>${esc(product().name)} · 消息推送</p></div><button class="icon-btn" data-close>×</button></header><div class="drawer-main">${stepNav()}<div class="drawer-body"><section class="drawer-content" id="ruleStepContent">${content()}</section></div></div><footer class="drawer-footer"><span class="save-hint">保存后按当前产品生效</span><div class="footer-actions"><button class="el-btn" data-draft>保存草稿</button><button class="el-btn" data-prev ${appState.ruleStep===1?"disabled":""}>上一步</button>${appState.ruleStep<3?'<button class="el-btn el-btn--primary" data-next>下一步</button>':'<button class="el-btn el-btn--primary" data-publish>保存并启用</button>'}</div></footer></aside></div>`}
function rerender(){const host=$("#ruleDrawer");if(!host)return;host.outerHTML=shell();wire();renderAnnotations(`rule${appState.ruleStep}`,`规则配置 · 步骤 ${appState.ruleStep}/3`)}
function triggerLabel(){const rule=appState.rule;if(rule.triggerType==="device"){const property=sources().properties.find(item=>item.id===rule.propertyId);return `设备：${property?.name||"属性"} ${rule.operator} ${rule.propertyValue}${property?.unit?` ${property.unit}`:""}`}if(rule.triggerType==="cloud"){const timer=sources().countdowns.find(item=>item.id===rule.cloudCountdownId);return `云端：${timer?.name||"计时器"} ≤ ${rule.cloudThresholdMinutes} ${timer?.unit||"分钟"}`}const item=sources().consumables.find(value=>value.id===rule.consumableId);return `耗材：${item?.name||"耗材"}${rule.consumableEvent==="empty"?"耗尽":"不足"}`}
function strategyLabel(){const rule=appState.rule,base=rule.category==="云计时器通知"?"同日合并":mode()==="discard"?`仅发送首条 · ${rule.minIntervalMinutes} 分钟`:"逐条发送",target=rule.systemNotificationEnabled?"消息中心 + 系统通知":"消息中心";return `${base} · ${target}`}
function save(status){const rule=appState.rule;const row={...rule,id:rule.id||`R-${2050+rules.length}`,productId:appState.selectedProductId,name:rule.name,product:product().name,trigger:triggerLabel(),title:appState.message.values["en-US"].title,languages:"1",strategy:strategyLabel(),status,updated:"2026-08-12 16:30"};const existing=rules.find(item=>item.id===rule.id);if(existing)Object.assign(existing,row);else rules.unshift(row);appState.rule.id=row.id;window.dispatchEvent(new Event("message-push:rule-changed"));showToast(status==="启用"?"规则已保存并启用":"规则草稿已保存");closeRuleDrawer()}
function insertPlaceholder(token){const host=$("#ruleDrawer"),field=appState.activeContentField||"title",input=$(`[data-content="${field}"]`,host);if(!input)return;const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=`${input.value.slice(0,start)}${token}${input.value.slice(end)}`;appState.message.values["en-US"][field]=input.value;input.focus();input.setSelectionRange(start+token.length,start+token.length);showToast("已插入内容")}
function wire(){const host=$("#ruleDrawer");host.querySelectorAll("[data-close]").forEach(item=>item.onclick=closeRuleDrawer);host.querySelectorAll("[data-step]").forEach(item=>item.onclick=()=>{appState.ruleStep=+item.dataset.step;rerender()});host.querySelectorAll("[data-rule]").forEach(item=>item.onchange=()=>{appState.rule[item.dataset.rule]=item.value;if(item.dataset.rule==="category"&&item.value==="云计时器通知")appState.rule.triggerType="cloud";rerender()});host.querySelector("[data-open-property-picker]")?.addEventListener("click",openPicker);host.querySelectorAll("[data-content]").forEach(item=>{item.oninput=()=>{appState.message.values["en-US"][item.dataset.content]=item.value};item.onfocus=()=>{appState.activeContentField=item.dataset.content;const hint=$(".placeholder-area>div span",host);if(hint)hint.textContent=`当前：${item.dataset.content==="body"?"Body":"Title"}`}});host.querySelectorAll("[data-insert-placeholder]").forEach(item=>item.onclick=()=>insertPlaceholder(item.dataset.insertPlaceholder));host.querySelectorAll('input[name="trigger"]').forEach(item=>item.onchange=()=>{appState.rule.triggerType=item.value;rerender()});host.querySelectorAll('input[name="mode"]').forEach(item=>item.onchange=()=>{appState.rule.reminderMode=item.value;rerender()});host.querySelector('input[name="system-notification"]')?.addEventListener("change",event=>{appState.rule.systemNotificationEnabled=event.target.checked;rerender()});host.querySelector("[data-preset]")?.addEventListener("change",event=>{appState.rule.presetLinkId=event.target.value});host.querySelector("[data-prev]")?.addEventListener("click",()=>{appState.ruleStep--;rerender()});host.querySelector("[data-next]")?.addEventListener("click",()=>{appState.ruleStep++;rerender()});host.querySelector("[data-draft]")?.addEventListener("click",()=>save("草稿"));host.querySelector("[data-publish]")?.addEventListener("click",()=>{if(host.querySelectorAll(".validation-fail").length){showToast("请先补全需要完善的内容","error");return}save("启用")})}
export function openRuleDrawer({edit=false}={}){appState.editingRule=edit;appState.ruleStep=1;$("#overlayRoot").innerHTML=shell();wire();renderAnnotations("rule1","规则配置 · 步骤 1/3")}
export function closeRuleDrawer(){closePicker();const host=$("#ruleDrawer");if(host)host.remove();renderAnnotations("rules","推送规则列表")}
export function resetRuleDraft(){appState.rule={...newRule(),productId:appState.selectedProductId};appState.message.values["en-US"]={title:"",body:""};appState.activeContentField="title"}
